begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('ef770000-0000-4000-8000-000000000001','bulk-owner@example.test',now()),
 ('ef770000-0000-4000-8000-000000000002','bulk-seller@example.test',now()),
 ('ef770000-0000-4000-8000-000000000003','bulk-staff@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic mail store','synthetic-mail-store',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','bulk-seller@example.test','')::text,true);
select register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'No email','','0700000000');
select is((preview_store_mail(current_setting('test.tenant')::uuid)->>'eligible')::int,0,'existing sellers never enrolled');
select is((preview_store_mail(current_setting('test.tenant')::uuid)->>'missingEmail')::int,1,'missing addresses counted');
select throws_ok($$select set_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,gen_random_uuid(),null,true)$$,'42501',null,'owner cannot grant consent');
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000002","role":"authenticated"}';
select set_config('test.consent',gen_random_uuid()::text,true);
select lives_ok($$select set_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.consent')::uuid,null,true)$$,'seller opts in');
select lives_ok($$select set_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.consent')::uuid,null,true)$$,'exact replay safe');
select throws_ok($$select set_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,gen_random_uuid(),null,false)$$,'P0001','CONSENT_CHANGED','stale consent cannot overwrite withdrawal');
select is(my_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'enabled','true','seller reads consent');
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((preview_store_mail(current_setting('test.tenant')::uuid)->>'eligible')::int,1,'only explicit opt-in eligible');
select set_config('test.preview',(preview_store_mail(current_setting('test.tenant')::uuid)->>'revision'),true);
select throws_ok($$select create_store_mail(current_setting('test.tenant')::uuid,gen_random_uuid(),'Hello','Opening hours',current_setting('test.preview'))$$,'P0001','STORE_EMAIL_MISSING','store reply address required');
select publish_store_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'{"address":{"street":"","postalCode":"","city":""},"contact":{"email":"store@example.test","phone":"","website":""},"openingHours":[],"accepts":"","concept":"","language":"sv"}');
select set_config('test.send',gen_random_uuid()::text,true);
select lives_ok($$select create_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,'Hello','Opening hours',current_setting('test.preview'))$$,'confirmed campaign created');
select lives_ok($$select create_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,'Hello','Opening hours',current_setting('test.preview'))$$,'confirmation retry cannot duplicate campaign');
select throws_ok($$select create_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,'Changed','Opening hours',current_setting('test.preview'))$$,'P0001','REQUEST_CONFLICT','same request cannot alter content');
select set_config('test.message',gen_random_uuid()::text,true);
select set_config('test.claim',claim_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,current_setting('test.message')::uuid,encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'))::text,true);
select is(current_setting('test.claim')::jsonb->>'to','bulk-seller@example.test','one recipient returned per claim');
select ok(claim_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,gen_random_uuid(),repeat('b',64)) ? 'waitMs','parallel dispatch throttled');
select record_communication_delivery(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'sent','synthetic');
select is(store_mail_history(current_setting('test.tenant')::uuid)->0->'outcomes'->>'sent','1','outcomes in existing log');
select is(store_mail_history(current_setting('test.tenant')::uuid)->0->>'remaining','0','committed claims never reappear as pending');
select set_config('test.pending',gen_random_uuid()::text,true);
select create_store_mail(current_setting('test.tenant')::uuid,current_setting('test.pending')::uuid,'Later message','Pending content',current_setting('test.preview'));
set local role anon;
select is(unsubscribe_store_mail(current_setting('test.message')::uuid,repeat('b',64)),false,'wrong unsubscribe capability refused');
select is(unsubscribe_store_mail(current_setting('test.message')::uuid,repeat('a',64)),true,'recipient can unsubscribe without login');
select is(unsubscribe_store_mail(current_setting('test.message')::uuid,repeat('a',64)),true,'unsubscribe is idempotent');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(my_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'enabled','false','withdrawal visible to seller');
select throws_ok($$select set_store_mail_consent(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,gen_random_uuid(),current_setting('test.consent')::uuid,true)$$,'P0001','CONSENT_CHANGED','old page cannot reverse unsubscribe');
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((preview_store_mail(current_setting('test.tenant')::uuid)->>'eligible')::int,0,'withdrawn seller excluded from new sends');
select pg_sleep(1.05);
select is(claim_store_mail(current_setting('test.tenant')::uuid,current_setting('test.pending')::uuid,gen_random_uuid(),repeat('c',64))->>'done','true','withdrawal also stops an already confirmed audience');
select is((select count(*)::int from seller_communications where store_mail_id=current_setting('test.pending')::uuid),0,'withdrawn recipient never queued');
select throws_ok($$select claim_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,current_setting('test.message')::uuid,repeat('c',64))$$,'P0001','REQUEST_CONFLICT','claimed message ID cannot be reused');
select throws_ok($$select create_store_mail(current_setting('test.tenant')::uuid,gen_random_uuid(),'Hello','Opening hours',current_setting('test.preview'))$$,'P0001','AUDIENCE_CHANGED','stale recipient preview refused');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'ef770000-0000-4000-8000-000000000003','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"ef770000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select preview_store_mail(current_setting('test.tenant')::uuid)$$,'42501',null,'staff cannot compose bulk mail');
select throws_ok($$select claim_store_mail(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,gen_random_uuid(),repeat('b',64))$$,'42501',null,'staff cannot dispatch bulk mail');
select throws_ok($$select store_mail_history(current_setting('test.tenant')::uuid)$$,'42501',null,'staff cannot read bulk history');
select set_config('test.other',create_tenant('Other mail store','other-mail-store',gen_random_uuid())::text,true);
select throws_ok($$select claim_store_mail(current_setting('test.other')::uuid,current_setting('test.send')::uuid,gen_random_uuid(),repeat('b',64))$$,'P0001','NOT_FOUND','cross-store campaign cannot be claimed');
select is(store_mail_history(current_setting('test.other')::uuid),'[]'::jsonb,'other store cannot read campaign history');
select throws_ok($$insert into seller_store_mail_consents(id,tenant_id,seller_id,enabled,email_hash,source) values(gen_random_uuid(),current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,true,repeat('c',64),'seller')$$,'42501',null,'direct consent writes denied');
reset role;
select ok(not has_function_privilege('anon','public.create_store_mail(uuid,uuid,text,text,text)','execute'),'anonymous sending denied');
select ok(not has_function_privilege('authenticated','komisio_private.store_mail_audience(uuid)','execute'),'audience internals not public');
select * from finish();
rollback;
